{
  "title": "Conversation Panel",
  "body": "<div class="panel"><h2>Conversation panel</h2><div id="total" class="total"></div><h3>Messages by role</h3><div id="roles" class="roles"></div><h3>Five most recent tool calls</h3><ul id="tools" class="tools"></ul><h3>Longest message</h3><div id="longest" class="longest"></div></div>",
  "css": ".panel{font-family:ui-sans-serif,system-ui,sans-serif;max-width:340px;padding:18px;background:linear-gradient(180deg,#ffffff,#f8fafc);border:1px solid #e2e8f0;border-radius:14px;color:#0f172a}.panel h2{margin:0 0 4px;font-size:17px}.panel h3{margin:16px 0 6px;font-size:11px;text-transform:uppercase;letter-spacing:.07em;color:#64748b}.total{font-size:13px;color:#475569}.roles{display:flex;flex-direction:column;gap:6px}.row{display:flex;justify-content:space-between;align-items:center;background:#fff;border:1px solid #e2e8f0;border-radius:8px;padding:6px 10px}.badge{font-size:12px;font-weight:600;padding:2px 8px;border-radius:999px}.badge-system{background:#f1f5f9;color:#475569}.badge-user{background:#dbeafe;color:#1d4ed8}.badge-assistant{background:#dcfce7;color:#15803d}.badge-tool{background:#ffedd5;color:#c2410c}.count{font-variant-numeric:tabular-nums;font-weight:700}.tools{margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:4px}.tool{display:flex;gap:8px;font-family:ui-monospace,monospace;font-size:13px;background:#fff;border:1px solid #e2e8f0;border-radius:8px;padding:5px 10px}.idx{color:#94a3b8}.empty{font-size:13px;color:#94a3b8}.longest{font-size:14px;font-weight:600}",
  "scripts": [
    "const msgs = ml.current.messages || [];
const counts = {};
for (const m of msgs) { counts[m.role] = (counts[m.role] ?? 0) + 1; }
const order = ["system", "user", "assistant", "tool"];
const roleNames = Object.keys(counts).sort((a, b) => (order.indexOf(a) === -1 ? 99 : order.indexOf(a)) - (order.indexOf(b) === -1 ? 99 : order.indexOf(b)));
const totalNode = root.byId["total"];
totalNode.text = String(msgs.length) + (msgs.length === 1 ? " message total" : " messages total");
totalNode.children = [];
const rolesNode = root.byId["roles"];
rolesNode.text = "";
rolesNode.children = roleNames.map((r) => ({ tag: "div", attrs: { class: "row" }, text: "", children: [ { tag: "span", attrs: { class: "badge badge-" + r }, text: r, children: [] }, { tag: "span", attrs: { class: "count" }, text: String(counts[r]), children: [] } ] }));
const calls = [];
for (const m of msgs) { if (m.tool_calls) { for (const tc of m.tool_calls) { calls.push(tc.function.name); } } }
const recent = calls.slice(-5).reverse();
const toolsNode = root.byId["tools"];
toolsNode.text = "";
toolsNode.children = recent.length ? recent.map((n, i) => ({ tag: "li", attrs: { class: "tool" }, text: "", children: [ { tag: "span", attrs: { class: "idx" }, text: String(i + 1) + ".", children: [] }, { tag: "span", attrs: { class: "name" }, text: n, children: [] } ] })) : [ { tag: "li", attrs: { class: "empty" }, text: "No tool calls yet", children: [] } ];
let longestLen = 0;
let longestRole = "";
for (const m of msgs) { const len = (m.content || "").length; if (len > longestLen) { longestLen = len; longestRole = m.role; } }
const longestNode = root.byId["longest"];
longestNode.text = msgs.length ? String(longestLen) + " characters" + (longestRole ? " — in a " + longestRole + " message" : "") : "No messages yet";
longestNode.children = [];"
  ]
}
